/*!
 * Crafted with ❤ by Salla
 */
/**
 * Rewrite a cart-add payload from the flat single-product shape into the products[] shape, so
 * the main product and every configured free product are added in one request:
 *
 *   id=X&quantity=N
 *     ↓
 *   products[0][id]=X&products[0][quantity]=N
 *   products[1][id]=Y₁&products[1][quantity]=1&products[1][options][o₁]=v₁
 *   products[2][id]=Y₂&products[2][quantity]=2&products[2][options][o₂]=v₂
 *
 * X has to move into products[0] rather than being left as a bare `id`, otherwise the gifts are
 * the only entries in the array. Bracket-notation string keys, not nested objects: the payload
 * may be backed by FormData (which stringifies anything non-scalar to "[object Object]"), and
 * MiniCheckoutRequest::prepareForValidation() expands these keys back into nested arrays.
 *
 * Only the payload is touched — `data.id`, which builds the request URL, is left alone.
 */
export function injectFreeProductsIntoPayload(payload, freeProducts) {
    if (!payload || !freeProducts?.length)
        return;
    // Two payload shapes reach this: the cart's FormDataWrapper (get/set/delete) from
    // `cart::before.add.item`, and the plain object `getElementSallaData()` hands the Apple Pay
    // flow. Normalize the three accessors so both work — a `set?.()` on a bare object would
    // silently no-op and drop every gift.
    const hasApi = typeof payload.set === 'function';
    const get = (k) => (hasApi ? payload.get?.(k) : payload[k]);
    const set = (k, v) => { hasApi ? payload.set(k, v) : (payload[k] = v); };
    const del = (k) => { hasApi ? payload.delete?.(k) : delete payload[k]; };
    // Read before deleting — X's own id/quantity become products[0].
    const mainId = get('id');
    const mainQty = get('quantity') || '1';
    if (mainId) {
        del('id');
        del('quantity');
        set('products[0][id]', String(mainId));
        set('products[0][quantity]', String(mainQty));
    }
    freeProducts.forEach((free, index) => {
        const slot = mainId ? index + 1 : index;
        set(`products[${slot}][id]`, String(free.productId));
        set(`products[${slot}][quantity]`, String(free.quantity));
        Object.entries(free.options).forEach(([optionId, value]) => {
            set(`products[${slot}][options][${optionId}]`, String(value));
        });
    });
}
